// source/blender/blenlib/tests/BLI_math_vector_types_test.cc:402
pub fn math_vec_types__SwizzleOperators()->Report{
let mut r=Report::default();
let mut v:v::V<f32,4> = v::construct::<f32,4>(&[&(1) as &dyn v::Components, &(2) as &dyn v::Components, &(3) as &dyn v::Components, &(4) as &dyn v::Components]);
v.set_swizzle([0,1],v.swizzle([0,1]) + (1 as f32));
  numeq!(r, v[0], 2);
  numeq!(r, v[1], 3);
  numeq!(r, v[2], 3);
  numeq!(r, v[3], 4);
v.set_swizzle([1,2],v.swizzle([1,2]) - (1 as f32));
  numeq!(r, v[0], 2);
  numeq!(r, v[1], 2);
  numeq!(r, v[2], 2);
  numeq!(r, v[3], 4);
v.set_swizzle([2,3],v.swizzle([2,3]) * (2 as f32));
  numeq!(r, v[0], 2);
  numeq!(r, v[1], 2);
  numeq!(r, v[2], 4);
  numeq!(r, v[3], 8);
v.set_swizzle([1,2,3],v.swizzle([1,2,3]) / (2 as f32));
  numeq!(r, v[0], 2);
  numeq!(r, v[1], 1);
  numeq!(r, v[2], 2);
  numeq!(r, v[3], 4);

  let mut i:v::V<i32,4> = v::construct::<i32,4>(&[&(1 << 0) as &dyn v::Components, &(1 << 2) as &dyn v::Components, &(1 << 3) as &dyn v::Components, &(1 << 4) as &dyn v::Components]);
  let mut a:v::V<i32,4> = -i.swizzle([0,1,2,3]);
  numeq!(r, a[0], -(1 << 0));
  numeq!(r, a[1], -(1 << 2));
  numeq!(r, a[2], -(1 << 3));
  numeq!(r, a[3], -(1 << 4));
  let mut b:v::V<i32,4> = !i.swizzle([0,1,2,3]);
  numeq!(r, b[0], !(1 << 0));
  numeq!(r, b[1], !(1 << 2));
  numeq!(r, b[2], !(1 << 3));
  numeq!(r, b[3], !(1 << 4));
i.set_swizzle([0,1],i.swizzle([0,1]) << (1 as i32));
  numeq!(r, i[0], 1 << 1);
  numeq!(r, i[1], 1 << 3);
  numeq!(r, i[2], 1 << 3);
  numeq!(r, i[3], 1 << 4);
i.set_swizzle([1,2],i.swizzle([1,2]) >> (1 as i32));
  numeq!(r, i[0], 1 << 1);
  numeq!(r, i[1], 1 << 2);
  numeq!(r, i[2], 1 << 2);
  numeq!(r, i[3], 1 << 4);
i.set_swizzle([0,1,2],i.swizzle([0,1,2]) & (2 as i32));
  numeq!(r, i[0], (1 << 1) & 2);
  numeq!(r, i[1], (1 << 2) & 2);
  numeq!(r, i[2], (1 << 2) & 2);
  numeq!(r, i[3], (1 << 4));
i.set_swizzle([1,2,3],i.swizzle([1,2,3]) | (2 as i32));
  numeq!(r, i[0], ((1 << 1) & 2));
  numeq!(r, i[1], ((1 << 2) & 2) | 2);
  numeq!(r, i[2], ((1 << 2) & 2) | 2);
  numeq!(r, i[3], (1 << 4) | 2);
i.set_swizzle([1,2],i.swizzle([1,2]) ^ (2 as i32));
  numeq!(r, i[0], ((1 << 1) & 2));
  numeq!(r, i[1], (((1 << 2) & 2) | 2) ^ 2);
  numeq!(r, i[2], (((1 << 2) & 2) | 2) ^ 2);
  numeq!(r, i[3], (1 << 4) | 2);
r
}

// source/blender/blenlib/tests/BLI_math_vector_types_test.cc:466
pub fn math_vec_types__SwizzleComparison()->Report{
let mut r=Report::default();
let mut a:v::V<i32,4> = v::construct::<i32,4>(&[&(1) as &dyn v::Components, &(2) as &dyn v::Components, &(3) as &dyn v::Components, &(4) as &dyn v::Components]);
  let mut b:v::V<i32,3> = v::construct::<i32,3>(&[&(1) as &dyn v::Components, &(2) as &dyn v::Components, &(3) as &dyn v::Components]);

  eq!(r, a.swizzle([0,1,2,3]) == a, true);
  eq!(r, a == a.swizzle([0,1,2,3]), true);
  eq!(r, a.swizzle([3,2,1,0]) == a.swizzle([0,1,2,3]), false);
  eq!(r, a.swizzle([0,1,2,3]) != a, false);
  eq!(r, a != a.swizzle([0,1,2,3]), false);
  eq!(r, a.swizzle([3,2,1,0]) != a.swizzle([0,1,2,3]), true);
  eq!(r, a.swizzle([0,1,2,2]) == b.swizzle([0,1,2,2]), true);
  eq!(r, a.swizzle([0,1,2,2]) != b.swizzle([0,1,2,2]), false);
r
}

