// source/blender/blenlib/tests/BLI_string_ref_test.cc:366
pub fn string_ref__TrimArbitrary()->Report{
let mut r=Report::default();

  let ref1=s::StringRef::new(&("test"));
  let ref2=s::StringRef::new(&("   test "));
  let ref3=s::StringRef::new(&(" \t  Urož with spaces "));
  let ref4=s::StringRef::new(&("žžžžleepyžžž"));
  eq!(r, ref1.trim("t"), "es");
  eq!(r, ref1.trim("te"), "s");
  eq!(r, ref1.trim("test"), "");
  eq!(r, ref2.trim("t"), "   test ");
  eq!(r, ref2.trim(""), "   test ");
  eq!(r, ref3.trim(" "), "\t  Urož with spaces");                          
  eq!(r, ref4.trim("ž"), "leepy");

r
}

